def scan_directory(path, config=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "scan_directory"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(status, code=None, message=None, project_id=None, scan_id=None, extra=None):
        logs = _ensure_logs()
        rid = f"req_{int(time.time()*1000)}_{hashlib.sha1((endpoint+str(time.time())).encode()).hexdigest()[:10]}"
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if project_id:
            row["project_id"] = project_id
        if scan_id:
            row["scan_id"] = scan_id
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _norm(p):
        return os.path.realpath(os.path.abspath(p))

    def _is_under(root, p):
        rn = _norm(root)
        pn = _norm(p)
        try:
            return os.path.commonpath([rn, pn]) == rn
        except Exception:
            return False

    def _gen_id(prefix):
        # semscan_01J... style is present, but keep deterministic-ish unique ids
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha1(str(time.time()).encode()).hexdigest()[:12]}"

    def _resolve_path_in_any_project(p):
        """
        Accept either absolute paths or paths relative to an active project's mcp_root_path.
        Pick a project where the resolved path stays under root.
        Do NOT require the path to exist on disk (offline service); only enforce root constraint.
        """
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        # Prefer the project where the resolved path is "closest" (longest root path).
        candidates = []
        for pr in projects:
            if not isinstance(pr, dict):
                continue
            if pr.get("status") != "active":
                continue
            root = pr.get("mcp_root_path")
            if not isinstance(root, str) or not root or not os.path.isabs(root):
                continue
            rootn = _norm(root)
            if os.path.isabs(p):
                resolved = _norm(p)
            else:
                resolved = _norm(os.path.join(rootn, p))
            if _is_under(rootn, resolved):
                candidates.append((len(rootn), pr, resolved, rootn))
        if not candidates:
            return None, None, None
        candidates.sort(key=lambda x: x[0], reverse=True)
        _, pr, resolved, rootn = candidates[0]
        return pr, resolved, rootn

    # Defaults / validate types
    if config is None:
        config = "auto"

    if not isinstance(path, str) or not path.strip():
        _append_log("error", "VALIDATION_ERROR", "`path` must be a non-empty string", extra={"path": path})
        return _err("VALIDATION_ERROR", "`path` must be a non-empty string", path=path)
    if not isinstance(config, str) or not config.strip():
        _append_log("error", "VALIDATION_ERROR", "`config` must be a non-empty string", extra={"config": config})
        return _err("VALIDATION_ERROR", "`config` must be a non-empty string", config=config)

    # Resolve project + scan path (allow relative input)
    project, scan_path_abs, root_abs = _resolve_path_in_any_project(path)
    if project is None:
        # business rule: must resolve under an active project's mcp_root_path
        _append_log(
            "error",
            "UNAUTHORIZED",
            "No active project workspace can serve this request (path must resolve under an active project's mcp_root_path).",
            extra={"path": path},
        )
        return _err(
            "UNAUTHORIZED",
            "No active project workspace can serve this request (path must resolve under an active project's mcp_root_path).",
            path=path,
        )

    # Validate config: "auto" or absolute or path under root when relative
    if config != "auto":
        if os.path.isabs(config):
            config_abs = _norm(config)
        else:
            config_abs = _norm(os.path.join(root_abs, config))
        if not _is_under(root_abs, config_abs):
            _append_log(
                "error",
                "VALIDATION_ERROR",
                "Business rule violated: config must be 'auto' or resolve under the project's mcp_root_path.",
                project_id=project.get("id"),
                extra={"config": config, "resolved": config_abs, "mcp_root_path": root_abs},
            )
            return _err(
                "VALIDATION_ERROR",
                "Business rule violated: config must be 'auto' or resolve under the project's mcp_root_path.",
                config=config,
                resolved=config_abs,
                mcp_root_path=root_abs,
            )
    else:
        config_abs = "auto"

    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []
    findings = _load("findings.json")
    if not isinstance(findings, list):
        findings = []

    scan_id = _gen_id("semscan")
    now = _now()

    # Create scan row (queued -> running -> succeeded) to reflect lifecycle.
    scan_row = {
        "id": scan_id,
        "project_id": project.get("id"),
        "scan_path": scan_path_abs,
        "config": config_abs,
        "results_file_path": None,
        "semgrep_version": None,
        "started_at": None,
        "finished_at": None,
        "status": "queued",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    scans.append(scan_row)
    _save("scans.json", scans)

    # Transition queued -> running
    scan_row["status"] = "running"
    scan_row["started_at"] = _now()
    scan_row["updated_at"] = scan_row["started_at"]
    _save("scans.json", scans)

    # "Run" semgrep offline: we do not execute Semgrep; instead produce an empty but valid results file and no new findings.
    # results_file_path must be absolute and under root; store under <root>/.semgrep/results/
    results_dir = os.path.join(root_abs, ".semgrep", "results")
    results_file_path = os.path.join(results_dir, f"{scan_row['started_at'].replace(':','-')}-{scan_id}.json")
    results_file_path = _norm(results_file_path)

    if not _is_under(root_abs, results_file_path):
        # This should never happen; treat as validation error rather than writing elsewhere.
        scan_row["status"] = "failed"
        scan_row["error_message"] = "Internal path resolution error: results_file_path escaped project root."
        scan_row["finished_at"] = _now()
        scan_row["updated_at"] = scan_row["finished_at"]
        _save("scans.json", scans)
        _append_log("error", "VALIDATION_ERROR", scan_row["error_message"], project_id=project.get("id"), scan_id=scan_id)
        return _err("VALIDATION_ERROR", scan_row["error_message"], results_file_path=results_file_path)

    # Try to write a minimal semgrep-like JSON results file (best-effort; if fails, mark scan failed)
    try:
        os.makedirs(os.path.dirname(results_file_path), exist_ok=True)
        payload = {
            "version": "offline",
            "results": [],
            "errors": [],
            "paths": {"scanned": [scan_path_abs]},
        }
        with open(results_file_path, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)
    except OSError as e:
        scan_row["status"] = "failed"
        scan_row["error_message"] = f"Failed to write results file: {e}"
        scan_row["finished_at"] = _now()
        scan_row["updated_at"] = scan_row["finished_at"]
        _save("scans.json", scans)
        _append_log("error", "CONFLICT", scan_row["error_message"], project_id=project.get("id"), scan_id=scan_id)
        return _err("CONFLICT", scan_row["error_message"], results_file_path=results_file_path)

    # Transition running -> succeeded
    scan_row["status"] = "succeeded"
    scan_row["results_file_path"] = results_file_path
    scan_row["finished_at"] = _now()
    scan_row["updated_at"] = scan_row["finished_at"]
    _save("scans.json", scans)

    # Upsert findings: no findings produced here, but keep behavior consistent (no-op without pretending affected >0)
    _save("findings.json", findings)

    response = {
        "scan": scan_row,
        "results_file": results_file_path,
        "findings": [],
        "metadata": {
            "project_id": project.get("id"),
            "scan_path": scan_path_abs,
            "config": config_abs,
        },
    }
    _append_log("ok", project_id=project.get("id"), scan_id=scan_id)
    return response

def list_rules(language=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_rules"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _log_and_return(status, payload, code=None, message=None):
        logs = _ensure_logs()
        row = {
            "id": f"req_{int(time.time()*1000)}_{hashlib.sha1((endpoint+str(time.time())).encode()).hexdigest()[:8]}",
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        logs.append(row)
        _save("request_logs.json", logs)
        return payload

    if language is not None and (not isinstance(language, str) or not language.strip()):
        return _log_and_return("error", _err("VALIDATION_ERROR", "`language` must be a non-empty string when provided"), "VALIDATION_ERROR", "`language` must be a non-empty string when provided")
    if isinstance(language, str):
        language = language.strip()

    projects = _load("projects.json")
    if not isinstance(projects, list):
        return _log_and_return("error", _err("UNAUTHORIZED", "No authenticated workspace context available"), "UNAUTHORIZED", "No authenticated workspace context available")

    # ambient: pick any active project (rules are scoped to project)
    project = None
    for p in projects:
        if isinstance(p, dict) and p.get("status") == "active":
            project = p
            break
    if project is None:
        return _log_and_return("error", _err("UNAUTHORIZED", "No active project available"), "UNAUTHORIZED", "No active project available")

    rules = _load("rules.json")
    if not isinstance(rules, list):
        rules = []

    out = []
    for r in rules:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project["id"]:
            continue
        if r.get("status") != "active":
            continue
        if language is not None and r.get("language") != language:
            continue
        item = {
            "rule_key": r.get("rule_key"),
            "language": r.get("language"),
            "severity": r.get("severity"),
            "source": r.get("source"),
        }
        if r.get("source") == "custom":
            item["rule_file_path"] = r.get("rule_file_path")
        out.append(item)

    return _log_and_return("ok", {"rules": out, "count": len(out)})

def analyze_results(results_file, **_extra):
    import json, os, datetime, time, hashlib, collections
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "analyze_results"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None, project_id=None, artifact_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{hashlib.sha1((endpoint+str(time.time())).encode()).hexdigest()[:10]}",
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if project_id:
            row["project_id"] = project_id
        if artifact_id:
            row["artifact_id"] = artifact_id
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _norm(p):
        try:
            return os.path.realpath(os.path.abspath(p))
        except Exception:
            return None

    def _under(root, p):
        try:
            rn = _norm(root)
            pn = _norm(p)
            if not rn or not pn:
                return False
            return os.path.commonpath([rn, pn]) == rn
        except Exception:
            return False

    def _resolve_project_for_path(p):
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        cands = []
        for pr in projects:
            if not isinstance(pr, dict):
                continue
            if pr.get("status") != "active":
                continue
            root = pr.get("mcp_root_path")
            if isinstance(root, str) and os.path.isabs(root) and _under(root, p):
                cands.append(pr)
        if not cands:
            return None
        cands.sort(key=lambda r: len(r.get("mcp_root_path") or ""), reverse=True)
        return cands[0]

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha1(str(time.time()).encode()).hexdigest()[:12]}"

    def _summarize(findings):
        by_sev = collections.Counter()
        by_rule = collections.Counter()
        by_lang = collections.Counter()
        top_files = collections.Counter()
        total = 0
        for f in findings:
            if not isinstance(f, dict):
                continue
            total += 1
            by_sev[f.get("severity") or "UNKNOWN"] += 1
            by_rule[f.get("rule_key") or ""] += 1
            by_lang[f.get("language") or ""] += 1
            top_files[f.get("file_path") or ""] += 1
        return {
            "total_findings": total,
            "counts_by_severity": dict(by_sev),
            "counts_by_rule": dict(by_rule),
            "counts_by_language": dict(by_lang),
            "top_files": [{"file_path": k, "count": v} for k, v in top_files.most_common(10) if k],
        }

    # Validate input
    if not isinstance(results_file, str) or not results_file.strip():
        _log("error", "VALIDATION_ERROR", "`results_file` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`results_file` must be a non-empty string")
    if not os.path.isabs(results_file):
        _log("error", "VALIDATION_ERROR", "`results_file` must be an absolute path")
        return _err("VALIDATION_ERROR", "`results_file` must be an absolute path")

    abs_results = _norm(results_file)
    project = _resolve_project_for_path(abs_results)
    if project is None:
        _log("error", "UNAUTHORIZED", "results_file is not within an active project MCP root path")
        return _err("UNAUTHORIZED", "results_file is not within an active project MCP root path", results_file=results_file)

    # Prefer stored findings when results_file matches a scan
    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []
    scan = None
    for s in scans:
        if isinstance(s, dict) and s.get("project_id") == project.get("id") and s.get("results_file_path") == abs_results:
            scan = s
            break

    findings_rows = _load("findings.json")
    if not isinstance(findings_rows, list):
        findings_rows = []

    if scan is not None:
        fnds = [f for f in findings_rows if isinstance(f, dict) and f.get("scan_id") == scan.get("id")]
        summary = _summarize(fnds)
        # Record analysis artifact as ready (analysis is a derived product)
        artifacts = _load("artifacts.json")
        if not isinstance(artifacts, list):
            artifacts = []
        art_id = _gen_id("semart")
        now = _now()
        art = {
            "id": art_id,
            "project_id": project.get("id"),
            "scan_id": scan.get("id"),
            "source_results_file_path": abs_results,
            "type": "analysis",
            "output_file_path": None,
            "export_format": None,
            "filter_criteria": None,
            "analysis_summary": summary,
            "comparison": None,
            "status": "ready",
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        artifacts.append(art)
        _save("artifacts.json", artifacts)
        _log("ok", project_id=project.get("id"), artifact_id=art_id)
        return {"artifact": art, "summary": summary}

    # If not a known scan, try to parse file if it exists; otherwise still allow if it exists in store? Real API needs file.
    if not os.path.isfile(abs_results):
        _log("error", "NOT_FOUND", "Results file not found", project_id=project.get("id"))
        return _err("NOT_FOUND", "Results file not found", results_file=results_file)

    try:
        with open(abs_results, encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError) as e:
        _log("error", "VALIDATION_ERROR", "results_file is not valid Semgrep JSON", project_id=project.get("id"), extra={"details": str(e)})
        return _err("VALIDATION_ERROR", "results_file is not valid Semgrep JSON", details=str(e), results_file=results_file)

    results = data.get("results", [])
    if not isinstance(results, list):
        _log("error", "VALIDATION_ERROR", "results_file is not valid Semgrep JSON: missing/invalid 'results' array", project_id=project.get("id"))
        return _err("VALIDATION_ERROR", "results_file is not valid Semgrep JSON: missing/invalid 'results' array", results_file=results_file)

    # Normalize minimal findings-like dicts for summary
    norm = []
    for r in results:
        if not isinstance(r, dict):
            continue
        rule_key = r.get("check_id") or r.get("rule_id") or r.get("id") or ""
        sev = (r.get("extra", {}).get("severity") if isinstance(r.get("extra"), dict) else None) or r.get("severity") or "INFO"
        msg = (r.get("extra", {}).get("message") if isinstance(r.get("extra"), dict) else None) or r.get("message") or ""
        lang = (r.get("extra", {}).get("metadata", {}).get("language") if isinstance(r.get("extra"), dict) and isinstance(r.get("extra", {}).get("metadata"), dict) else None) or None
        path = None
        if isinstance(r.get("path"), str):
            path = r.get("path")
        elif isinstance(r.get("path"), dict) and isinstance(r.get("path").get("value"), str):
            path = r.get("path").get("value")
        start = r.get("start", {}) if isinstance(r.get("start"), dict) else {}
        end = r.get("end", {}) if isinstance(r.get("end"), dict) else {}
        norm.append({
            "rule_key": rule_key,
            "severity": sev,
            "language": lang,
            "file_path": path or "",
            "start_line": int(start.get("line") or 1) if isinstance(start.get("line"), (int, float, str)) else 1,
            "start_col": int(start.get("col") or 1) if isinstance(start.get("col"), (int, float, str)) else 1,
            "end_line": int(end.get("line") or 1) if isinstance(end.get("line"), (int, float, str)) else 1,
            "end_col": int(end.get("col") or 1) if isinstance(end.get("col"), (int, float, str)) else 1,
            "message": msg or "",
        })

    summary = _summarize(norm)

    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []
    art_id = _gen_id("semart")
    now = _now()
    art = {
        "id": art_id,
        "project_id": project.get("id"),
        "scan_id": None,
        "source_results_file_path": abs_results,
        "type": "analysis",
        "output_file_path": None,
        "export_format": None,
        "filter_criteria": None,
        "analysis_summary": summary,
        "comparison": None,
        "status": "ready",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    artifacts.append(art)
    _save("artifacts.json", artifacts)

    _log("ok", project_id=project.get("id"), artifact_id=art_id)
    return {"artifact": art, "summary": summary}

def create_rule(output_path, pattern, language, message, severity=None, id=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_rule"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(status, code=None, message=None, project_id=None, rule_id=None, extra=None):
        logs = _ensure_logs()
        rid = f"req_{int(time.time()*1000)}_{hashlib.sha1((endpoint+str(time.time())).encode()).hexdigest()[:10]}"
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if project_id:
            row["project_id"] = project_id
        if rule_id:
            row["rule_id"] = rule_id
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _norm(p):
        return os.path.realpath(os.path.abspath(p))

    def _is_under(root, p):
        rn = _norm(root)
        pn = _norm(p)
        try:
            return os.path.commonpath([rn, pn]) == rn
        except Exception:
            return False

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha1(str(time.time()).encode()).hexdigest()[:12]}"

    def _choose_project_for_output(p):
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        cands = []
        for pr in projects:
            if not isinstance(pr, dict) or pr.get("status") != "active":
                continue
            root = pr.get("mcp_root_path")
            if not isinstance(root, str) or not root or not os.path.isabs(root):
                continue
            rootn = _norm(root)
            if os.path.isabs(p):
                resolved = _norm(p)
            else:
                resolved = _norm(os.path.join(rootn, p))
            if _is_under(rootn, resolved):
                cands.append((len(rootn), pr, resolved, rootn))
        if not cands:
            return None, None, None
        cands.sort(key=lambda x: x[0], reverse=True)
        _, pr, resolved, rootn = cands[0]
        return pr, resolved, rootn

    # Defaults
    if severity is None:
        severity = "WARNING"
    if id is None:
        id = "custom_rule"

    # Validate required params (per tool schema)
    if not isinstance(output_path, str) or not output_path.strip():
        _append_log("error", "VALIDATION_ERROR", "`output_path` must be a non-empty string", extra={"output_path": output_path})
        return _err("VALIDATION_ERROR", "`output_path` must be a non-empty string", output_path=output_path)
    if not isinstance(pattern, str) or not pattern.strip():
        _append_log("error", "VALIDATION_ERROR", "`pattern` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`pattern` must be a non-empty string", pattern=pattern)
    if not isinstance(language, str) or not language.strip():
        _append_log("error", "VALIDATION_ERROR", "`language` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`language` must be a non-empty string", language=language)
    if not isinstance(message, str) or not message.strip():
        _append_log("error", "VALIDATION_ERROR", "`message` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`message` must be a non-empty string", message=message)
    if not isinstance(severity, str) or severity not in ("ERROR", "WARNING", "INFO"):
        _append_log("error", "VALIDATION_ERROR", "`severity` must be one of ERROR, WARNING, INFO", extra={"severity": severity})
        return _err("VALIDATION_ERROR", "`severity` must be one of ERROR, WARNING, INFO", severity=severity)
    if not isinstance(id, str) or not id.strip():
        _append_log("error", "VALIDATION_ERROR", "`id` must be a non-empty string", extra={"id": id})
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string", id=id)

    # Relaxed path handling: accept relative output_path and resolve under an active project root.
    project, out_abs, root_abs = _choose_project_for_output(output_path)
    if project is None:
        _append_log(
            "error",
            "UNAUTHORIZED",
            "No active project workspace can serve this request (output_path must resolve under an active project's mcp_root_path).",
            extra={"output_path": output_path},
        )
        return _err(
            "UNAUTHORIZED",
            "No active project workspace can serve this request (output_path must resolve under an active project's mcp_root_path).",
            output_path=output_path,
        )

    # Business rule: output_path must resolve under root, and is stored as absolute; must be absolute in stored rule.
    if not _is_under(root_abs, out_abs):
        _append_log(
            "error",
            "VALIDATION_ERROR",
            "Business rule violated: output_path must resolve under the project's mcp_root_path.",
            project_id=project.get("id"),
            extra={"output_path": output_path, "resolved": out_abs, "mcp_root_path": root_abs},
        )
        return _err(
            "VALIDATION_ERROR",
            "Business rule violated: output_path must resolve under the project's mcp_root_path.",
            output_path=output_path,
            resolved=out_abs,
            mcp_root_path=root_abs,
        )

    # Ensure parent directory exists (create it; offline-friendly). If cannot create, return NOT_FOUND per tool description.
    parent = os.path.dirname(out_abs)
    try:
        os.makedirs(parent, exist_ok=True)
    except OSError:
        _append_log(
            "error",
            "NOT_FOUND",
            "Parent directory for `output_path` does not exist and could not be created.",
            project_id=project.get("id"),
            extra={"output_path": out_abs},
        )
        return _err("NOT_FOUND", "Parent directory for `output_path` does not exist and could not be created.", output_path=out_abs)

    # Upsert rule by (project_id, rule_key=id) only if existing status != 'deleted'
    rules = _load("rules.json")
    if not isinstance(rules, list):
        rules = []

    existing = None
    for r in rules:
        if isinstance(r, dict) and r.get("project_id") == project.get("id") and r.get("rule_key") == id:
            existing = r
            break

    if existing is not None and existing.get("status") == "deleted":
        _append_log(
            "error",
            "INVALID_TRANSITION",
            "Business rule violated: cannot upsert a rule whose status is 'deleted'.",
            project_id=project.get("id"),
            rule_id=existing.get("id"),
        )
        return _err(
            "INVALID_TRANSITION",
            "Business rule violated: cannot upsert a rule whose status is 'deleted'.",
            rule_key=id,
            rule_id=existing.get("id"),
        )

    # Persist rule file
    rule_yaml = (
        "rules:\n"
        f"  - id: {id}\n"
        f"    languages: [{language}]\n"
        f"    message: {message}\n"
        f"    severity: {severity}\n"
        "    patterns:\n"
        f"      - pattern: {pattern}\n"
    )
    try:
        with open(out_abs, "w", encoding="utf-8") as f:
            f.write(rule_yaml)
    except OSError as e:
        _append_log("error", "CONFLICT", f"Failed to write rule file: {e}", project_id=project.get("id"), extra={"output_path": out_abs})
        return _err("CONFLICT", f"Failed to write rule file: {e}", output_path=out_abs)

    now = _now()
    if existing is None:
        rule_row = {
            "id": _gen_id("semrule"),
            "project_id": project.get("id"),
            "rule_key": id,
            "source": "custom",
            "language": language,
            "pattern": pattern,
            "message": message,
            "severity": severity,
            "rule_file_path": out_abs,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        rules.append(rule_row)
    else:
        existing["source"] = "custom"
        existing["language"] = language
        existing["pattern"] = pattern
        existing["message"] = message
        existing["severity"] = severity
        existing["rule_file_path"] = out_abs
        existing["status"] = "active"
        existing["updated_at"] = now
        rule_row = existing

    _save("rules.json", rules)
    _append_log("ok", project_id=project.get("id"), rule_id=rule_row.get("id"), extra={"rule_key": id})
    return {"rule": rule_row}

def filter_results(results_file, severity=None, rule_id=None, path_pattern=None, language=None, message_pattern=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "filter_results"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, code=None, message=None, project_id=None, artifact_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{hashlib.sha1((endpoint+str(time.time())).encode()).hexdigest()[:10]}",
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if project_id:
            row["project_id"] = project_id
        if artifact_id:
            row["artifact_id"] = artifact_id
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _norm(p):
        try:
            return os.path.realpath(os.path.abspath(p))
        except Exception:
            return None

    def _under(root, p):
        try:
            rn = _norm(root)
            pn = _norm(p)
            if not rn or not pn:
                return False
            return os.path.commonpath([rn, pn]) == rn
        except Exception:
            return False

    def _resolve_project_for_path(p):
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        cands = []
        for pr in projects:
            if not isinstance(pr, dict):
                continue
            if pr.get("status") != "active":
                continue
            root = pr.get("mcp_root_path")
            if isinstance(root, str) and os.path.isabs(root) and _under(root, p):
                cands.append(pr)
        if not cands:
            return None
        cands.sort(key=lambda r: len(r.get("mcp_root_path") or ""), reverse=True)
        return cands[0]

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha1(str(time.time()).encode()).hexdigest()[:12]}"

    def _parse_regex(pat, name):
        if pat is None:
            return None, None
        if not isinstance(pat, str):
            return None, _err("VALIDATION_ERROR", f"`{name}` must be a string", value=pat)
        try:
            return re.compile(pat), None
        except re.error as e:
            return None, _err("VALIDATION_ERROR", f"`{name}` is not a valid regex", details=str(e), value=pat)

    # Validate
    if not isinstance(results_file, str) or not results_file.strip():
        _log("error", "VALIDATION_ERROR", "`results_file` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`results_file` must be a non-empty string")
    if not os.path.isabs(results_file):
        _log("error", "VALIDATION_ERROR", "`results_file` must be an absolute path")
        return _err("VALIDATION_ERROR", "`results_file` must be an absolute path")

    abs_results = _norm(results_file)
    project = _resolve_project_for_path(abs_results)
    if project is None:
        _log("error", "UNAUTHORIZED", "results_file is not within an active project MCP root path")
        return _err("UNAUTHORIZED", "results_file is not within an active project MCP root path", results_file=results_file)

    if severity is not None:
        if not isinstance(severity, str) or severity not in ("ERROR", "WARNING", "INFO"):
            _log("error", "VALIDATION_ERROR", "`severity` must be one of ERROR, WARNING, INFO", project_id=project.get("id"))
            return _err("VALIDATION_ERROR", "`severity` must be one of ERROR, WARNING, INFO", severity=severity)
    if rule_id is not None and (not isinstance(rule_id, str) or not rule_id.strip()):
        _log("error", "VALIDATION_ERROR", "`rule_id` must be a non-empty string", project_id=project.get("id"))
        return _err("VALIDATION_ERROR", "`rule_id` must be a non-empty string")
    if language is not None and (not isinstance(language, str) or not language.strip()):
        _log("error", "VALIDATION_ERROR", "`language` must be a non-empty string", project_id=project.get("id"))
        return _err("VALIDATION_ERROR", "`language` must be a non-empty string")

    path_re, err = _parse_regex(path_pattern, "path_pattern")
    if err:
        _log("error", err["error"]["code"], err["error"]["message"], project_id=project.get("id"), extra=err["error"])
        return err
    msg_re, err = _parse_regex(message_pattern, "message_pattern")
    if err:
        _log("error", err["error"]["code"], err["error"]["message"], project_id=project.get("id"), extra=err["error"])
        return err

    # Determine known scan vs parse file
    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []
    scan = None
    for s in scans:
        if isinstance(s, dict) and s.get("project_id") == project.get("id") and s.get("results_file_path") == abs_results:
            scan = s
            break

    source = None
    findings = []
    if scan is not None:
        all_findings = _load("findings.json")
        if not isinstance(all_findings, list):
            all_findings = []
        findings = [f for f in all_findings if isinstance(f, dict) and f.get("scan_id") == scan.get("id")]
        source = "findings_table"
    else:
        # Parse file; if file not found, error.
        if not os.path.isfile(abs_results):
            _log("error", "NOT_FOUND", "Results file not found", project_id=project.get("id"))
            return _err("NOT_FOUND", "Results file not found", results_file=results_file)
        try:
            with open(abs_results, encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, json.JSONDecodeError) as e:
            _log("error", "VALIDATION_ERROR", "results_file is not valid Semgrep JSON", project_id=project.get("id"), extra={"details": str(e)})
            return _err("VALIDATION_ERROR", "results_file is not valid Semgrep JSON", details=str(e), results_file=results_file)
        res = data.get("results", [])
        if not isinstance(res, list):
            _log("error", "VALIDATION_ERROR", "results_file is not valid Semgrep JSON: missing/invalid 'results' array", project_id=project.get("id"))
            return _err("VALIDATION_ERROR", "results_file is not valid Semgrep JSON: missing/invalid 'results' array", results_file=results_file)

        # Create imported_results_reference artifact (optional rule)
        artifacts = _load("artifacts.json")
        if not isinstance(artifacts, list):
            artifacts = []
        ref_id = _gen_id("semart")
        now = _now()
        ref = {
            "id": ref_id,
            "project_id": project.get("id"),
            "scan_id": None,
            "source_results_file_path": abs_results,
            "type": "imported_results_reference",
            "output_file_path": None,
            "export_format": None,
            "filter_criteria": None,
            "analysis_summary": None,
            "comparison": None,
            "status": "ready",
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        artifacts.append(ref)
        _save("artifacts.json", artifacts)

        # Normalize to finding-like dicts for filtering
        for r in res:
            if not isinstance(r, dict):
                continue
            rule_key = r.get("check_id") or r.get("rule_id") or r.get("id") or ""
            sev = (r.get("extra", {}).get("severity") if isinstance(r.get("extra"), dict) else None) or r.get("severity") or "INFO"
            msg = (r.get("extra", {}).get("message") if isinstance(r.get("extra"), dict) else None) or r.get("message") or ""
            lang = (r.get("extra", {}).get("metadata", {}).get("language") if isinstance(r.get("extra"), dict) and isinstance(r.get("extra", {}).get("metadata"), dict) else None) or None
            path = None
            if isinstance(r.get("path"), str):
                path = r.get("path")
            elif isinstance(r.get("path"), dict) and isinstance(r.get("path").get("value"), str):
                path = r.get("path").get("value")
            findings.append({
                "rule_key": rule_key,
                "severity": sev,
                "language": lang,
                "file_path": path or "",
                "message": msg or "",
                "raw": r,
            })
        source = "parsed_results_file"

    # Apply AND filters
    def _match(f):
        if severity is not None and f.get("severity") != severity:
            return False
        if rule_id is not None and f.get("rule_key") != rule_id:
            return False
        if language is not None and (f.get("language") or "") != language:
            return False
        fp = f.get("file_path") or ""
        if path_re is not None and not path_re.search(fp):
            return False
        msg = f.get("message") or ""
        if msg_re is not None and not msg_re.search(msg):
            return False
        return True

    filtered = [f for f in findings if isinstance(f, dict) and _match(f)]

    # Create filtered_results artifact
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []
    art_id = _gen_id("semart")
    now = _now()
    art = {
        "id": art_id,
        "project_id": project.get("id"),
        "scan_id": scan.get("id") if isinstance(scan, dict) else None,
        "source_results_file_path": abs_results,
        "type": "filtered_results",
        "output_file_path": None,
        "export_format": None,
        "filter_criteria": {
            "severity": severity,
            "rule_id": rule_id,
            "path_pattern": path_pattern,
            "language": language,
            "message_pattern": message_pattern,
        },
        "analysis_summary": None,
        "comparison": None,
        "status": "ready",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    artifacts.append(art)
    _save("artifacts.json", artifacts)

    _log("ok", project_id=project.get("id"), artifact_id=art_id, extra={"source": source, "count": len(filtered)})
    return {"artifact": art, "findings": filtered, "count": len(filtered), "source": source}

def export_results(results_file, output_file, format=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "export_results"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(status, code=None, message=None, project_id=None, artifact_id=None, extra=None):
        logs = _ensure_logs()
        rid = f"req_{int(time.time()*1000)}_{hashlib.sha1((endpoint+str(time.time())).encode()).hexdigest()[:10]}"
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if project_id:
            row["project_id"] = project_id
        if artifact_id:
            row["artifact_id"] = artifact_id
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _norm(p):
        return os.path.realpath(os.path.abspath(p))

    def _is_under(root, p):
        rn = _norm(root)
        pn = _norm(p)
        try:
            return os.path.commonpath([rn, pn]) == rn
        except Exception:
            return False

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha1(str(time.time()).encode()).hexdigest()[:12]}"

    def _choose_project_for_paths(*paths):
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        candidates = []
        for pr in projects:
            if not isinstance(pr, dict) or pr.get("status") != "active":
                continue
            root = pr.get("mcp_root_path")
            if not isinstance(root, str) or not root or not os.path.isabs(root):
                continue
            rootn = _norm(root)
            resolved_all = []
            ok = True
            for p in paths:
                if os.path.isabs(p):
                    rp = _norm(p)
                else:
                    rp = _norm(os.path.join(rootn, p))
                if not _is_under(rootn, rp):
                    ok = False
                    break
                resolved_all.append(rp)
            if ok:
                candidates.append((len(rootn), pr, rootn, resolved_all))
        if not candidates:
            return None, None, None
        candidates.sort(key=lambda x: x[0], reverse=True)
        _, pr, rootn, resolved_all = candidates[0]
        return pr, rootn, resolved_all

    if format is None:
        format = "text"

    # Validate basic types/enums
    if not isinstance(results_file, str) or not results_file.strip():
        _append_log("error", "VALIDATION_ERROR", "`results_file` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`results_file` must be a non-empty string", results_file=results_file)
    if not isinstance(output_file, str) or not output_file.strip():
        _append_log("error", "VALIDATION_ERROR", "`output_file` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`output_file` must be a non-empty string", output_file=output_file)
    if not isinstance(format, str) or format not in ("json", "sarif", "text"):
        _append_log("error", "VALIDATION_ERROR", "`format` must be one of json, sarif, text", extra={"format": format})
        return _err("VALIDATION_ERROR", "`format` must be one of json, sarif, text", format=format)

    # Resolve a project that can serve BOTH paths (allow relative inputs, but must resolve under root)
    project, root_abs, resolved = _choose_project_for_paths(results_file, output_file)
    if project is None:
        _append_log(
            "error",
            "UNAUTHORIZED",
            "No active project workspace can serve this request (paths must resolve under an active project's mcp_root_path).",
            extra={"results_file": results_file, "output_file": output_file},
        )
        return _err(
            "UNAUTHORIZED",
            "No active project workspace can serve this request (paths must resolve under an active project's mcp_root_path).",
            results_file=results_file,
            output_file=output_file,
        )
    results_abs, output_abs = resolved[0], resolved[1]

    # Determine scan linkage by path (do not require file exists; datastore may reference it)
    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []
    scan = None
    for s in scans:
        if isinstance(s, dict) and s.get("results_file_path") == results_abs:
            scan = s
            break

    # Gather findings if known scan, else parse file if present.
    export_payload = None
    used_findings = []
    parse_errors = None

    if scan is not None:
        all_findings = _load("findings.json")
        if not isinstance(all_findings, list):
            all_findings = []
        for f in all_findings:
            if isinstance(f, dict) and f.get("scan_id") == scan.get("id"):
                used_findings.append(f)
        # Create a semgrep-like payload from findings (minimal)
        export_payload = {
            "version": scan.get("semgrep_version") or "offline",
            "results": [f.get("raw") if isinstance(f.get("raw"), dict) else {
                "check_id": f.get("rule_key"),
                "path": f.get("file_path"),
                "start": {"line": f.get("start_line"), "col": f.get("start_col")},
                "end": {"line": f.get("end_line"), "col": f.get("end_col")},
                "extra": {"message": f.get("message"), "severity": f.get("severity"), "language": f.get("language")},
            } for f in used_findings],
            "errors": [],
            "paths": {"scanned": [scan.get("scan_path")] if scan.get("scan_path") else []},
        }
    else:
        # Prefer parsing only if file exists; otherwise this is NOT_FOUND (but only after checking known scan linkage).
        if not os.path.exists(results_abs):
            _append_log(
                "error",
                "NOT_FOUND",
                "Input results file does not exist and does not match any known scan results_file_path.",
                project_id=project.get("id"),
                extra={"results_file": results_abs},
            )
            return _err(
                "NOT_FOUND",
                "Input results file does not exist and does not match any known scan results_file_path.",
                results_file=results_abs,
            )
        try:
            with open(results_abs, "r", encoding="utf-8") as f:
                export_payload = json.load(f)
        except json.JSONDecodeError as e:
            parse_errors = f"failed to parse results file: {e}"
        except OSError as e:
            parse_errors = f"failed to read results file: {e}"

        if parse_errors is not None:
            _append_log("error", "VALIDATION_ERROR", parse_errors, project_id=project.get("id"), extra={"results_file": results_abs})
            return _err("VALIDATION_ERROR", parse_errors, results_file=results_abs)

    # Ensure output directory exists (create it; if cannot, NOT_FOUND per tool description)
    try:
        os.makedirs(os.path.dirname(output_abs), exist_ok=True)
    except OSError:
        _append_log("error", "NOT_FOUND", "Output parent directory does not exist and could not be created.", project_id=project.get("id"), extra={"output_file": output_abs})
        return _err("NOT_FOUND", "Output parent directory does not exist and could not be created.", output_file=output_abs)

    # Create artifact row with lifecycle transitions
    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []
    art_id = _gen_id("semart")
    now = _now()
    art = {
        "id": art_id,
        "project_id": project.get("id"),
        "scan_id": scan.get("id") if isinstance(scan, dict) else None,
        "source_results_file_path": results_abs,
        "type": "export",
        "output_file_path": output_abs,
        "export_format": format,
        "filter_criteria": None,
        "analysis_summary": None,
        "comparison": None,
        "status": "created",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    artifacts.append(art)
    _save("artifacts.json", artifacts)

    # Transition created -> processing
    art["status"] = "processing"
    art["updated_at"] = _now()
    _save("artifacts.json", artifacts)

    # Materialize output
    try:
        if format == "json":
            with open(output_abs, "w", encoding="utf-8") as f:
                json.dump(export_payload, f, ensure_ascii=False, indent=2)
        elif format == "text":
            results = export_payload.get("results") if isinstance(export_payload, dict) else None
            if not isinstance(results, list):
                results = []
            lines = []
            for r in results:
                if isinstance(r, dict):
                    check_id = r.get("check_id") or r.get("rule_id") or r.get("id") or "unknown-rule"
                    path = r.get("path") or (r.get("extra") or {}).get("path") or "unknown-file"
                    start = r.get("start") or {}
                    msg = ((r.get("extra") or {}).get("message")) or r.get("message") or ""
                    sev = ((r.get("extra") or {}).get("severity")) or r.get("severity") or ""
                    loc = ""
                    if isinstance(start, dict) and start.get("line"):
                        loc = f":{start.get('line')}"
                        if start.get("col"):
                            loc += f":{start.get('col')}"
                    lines.append(f"{path}{loc} [{sev}] {check_id} {msg}".strip())
            with open(output_abs, "w", encoding="utf-8") as f:
                f.write("\n".join(lines) + ("\n" if lines else ""))
        else:  # sarif
            results = export_payload.get("results") if isinstance(export_payload, dict) else None
            if not isinstance(results, list):
                results = []
            sarif = {
                "version": "2.1.0",
                "$schema": "https://json.schemastore.org/sarif-2.1.0.json",
                "runs": [{
                    "tool": {"driver": {"name": "semgrep-offline", "version": export_payload.get("version") if isinstance(export_payload, dict) else "offline"}},
                    "results": [],
                }],
            }
            sarif_results = sarif["runs"][0]["results"]
            for r in results:
                if not isinstance(r, dict):
                    continue
                msg = ((r.get("extra") or {}).get("message")) or r.get("message") or ""
                rule_id = r.get("check_id") or r.get("rule_id") or r.get("id") or "unknown-rule"
                path = r.get("path") or "unknown-file"
                start = r.get("start") or {}
                region = {}
                if isinstance(start, dict):
                    if isinstance(start.get("line"), int):
                        region["startLine"] = start["line"]
                    if isinstance(start.get("col"), int):
                        region["startColumn"] = start["col"]
                sarif_results.append({
                    "ruleId": rule_id,
                    "message": {"text": msg},
                    "locations": [{
                        "physicalLocation": {
                            "artifactLocation": {"uri": path},
                            "region": region if region else {},
                        }
                    }],
                })
            with open(output_abs, "w", encoding="utf-8") as f:
                json.dump(sarif, f, ensure_ascii=False, indent=2)
    except OSError as e:
        art["status"] = "failed"
        art["error_message"] = f"write {output_abs}: {e}"
        art["updated_at"] = _now()
        _save("artifacts.json", artifacts)
        _append_log("error", "CONFLICT", art["error_message"], project_id=project.get("id"), artifact_id=art_id)
        return _err("CONFLICT", art["error_message"], artifact_id=art_id, output_file=output_abs)

    # Transition processing -> ready
    art["status"] = "ready"
    art["updated_at"] = _now()
    _save("artifacts.json", artifacts)

    _append_log("ok", project_id=project.get("id"), artifact_id=art_id, extra={"format": format})
    return {
        "artifact": art,
        "export": {
            "format": format,
            "output_file": output_abs,
            "results_file": results_abs,
            "scan_id": scan.get("id") if isinstance(scan, dict) else None,
            "finding_count": len(used_findings) if scan is not None else None,
        },
    }

def compare_results(old_results, new_results, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "compare_results"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(status, code=None, message=None, project_id=None, artifact_id=None, extra=None):
        logs = _ensure_logs()
        rid = f"req_{int(time.time()*1000)}_{hashlib.sha1((endpoint+str(time.time())).encode()).hexdigest()[:10]}"
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if project_id:
            row["project_id"] = project_id
        if artifact_id:
            row["artifact_id"] = artifact_id
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _norm(p):
        return os.path.realpath(os.path.abspath(p))

    def _is_under(root, p):
        rn = _norm(root)
        pn = _norm(p)
        try:
            return os.path.commonpath([rn, pn]) == rn
        except Exception:
            return False

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha1(str(time.time()).encode()).hexdigest()[:12]}"

    def _choose_project_for_paths(*paths):
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        candidates = []
        for pr in projects:
            if not isinstance(pr, dict) or pr.get("status") != "active":
                continue
            root = pr.get("mcp_root_path")
            if not isinstance(root, str) or not root or not os.path.isabs(root):
                continue
            rootn = _norm(root)
            resolved_all = []
            ok = True
            for p in paths:
                if os.path.isabs(p):
                    rp = _norm(p)
                else:
                    rp = _norm(os.path.join(rootn, p))
                if not _is_under(rootn, rp):
                    ok = False
                    break
                resolved_all.append(rp)
            if ok:
                candidates.append((len(rootn), pr, rootn, resolved_all))
        if not candidates:
            return None, None, None
        candidates.sort(key=lambda x: x[0], reverse=True)
        _, pr, rootn, resolved_all = candidates[0]
        return pr, rootn, resolved_all

    def _fingerprint_from_result(r):
        # Stable-ish and consistent with "rule_key + file_path + location + message" intent.
        if not isinstance(r, dict):
            return None
        rule = r.get("check_id") or r.get("rule_id") or r.get("id") or ""
        path = r.get("path") or ""
        start = r.get("start") or {}
        end = r.get("end") or {}
        msg = ((r.get("extra") or {}).get("message")) or r.get("message") or ""
        if not isinstance(start, dict):
            start = {}
        if not isinstance(end, dict):
            end = {}
        sline = start.get("line") or ""
        scol = start.get("col") or ""
        eline = end.get("line") or ""
        ecol = end.get("col") or ""
        base = f"{rule}|{path}|{sline}:{scol}-{eline}:{ecol}|{msg}"
        return hashlib.sha1(base.encode("utf-8", "ignore")).hexdigest()

    def _load_results_payload(path_abs):
        # Prefer findings if this path corresponds to a scan; otherwise parse file.
        scans = _load("scans.json")
        if not isinstance(scans, list):
            scans = []
        scan = None
        for s in scans:
            if isinstance(s, dict) and s.get("results_file_path") == path_abs:
                scan = s
                break
        if scan is not None:
            all_findings = _load("findings.json")
            if not isinstance(all_findings, list):
                all_findings = []
            fps = set()
            # Use stored finding.fingerprint if present; else derive from raw.
            for f in all_findings:
                if not isinstance(f, dict) or f.get("scan_id") != scan.get("id"):
                    continue
                fp = f.get("fingerprint")
                if isinstance(fp, str) and fp:
                    fps.add(fp)
                else:
                    raw = f.get("raw") if isinstance(f.get("raw"), dict) else None
                    if raw is not None:
                        d = _fingerprint_from_result(raw)
                        if d:
                            fps.add(d)
            return {"scan": scan, "fingerprints": fps, "source": "findings"}
        # Not a known scan: parse file. Require existence.
        if not os.path.exists(path_abs):
            return {"error": _err("NOT_FOUND", "Input results file does not exist and does not match any known scan results_file_path.", results_file=path_abs)}
        try:
            with open(path_abs, "r", encoding="utf-8") as f:
                payload = json.load(f)
        except json.JSONDecodeError as e:
            return {"error": _err("VALIDATION_ERROR", f"Invalid Semgrep JSON: {e}", results_file=path_abs)}
        except OSError as e:
            return {"error": _err("CONFLICT", f"Failed to read results file: {e}", results_file=path_abs)}
        results = payload.get("results") if isinstance(payload, dict) else None
        if not isinstance(results, list):
            results = []
        fps = set()
        for r in results:
            fp = _fingerprint_from_result(r) if isinstance(r, dict) else None
            if fp:
                fps.add(fp)
        return {"scan": None, "fingerprints": fps, "source": "parsed"}

    # Validate
    if not isinstance(old_results, str) or not old_results.strip():
        _append_log("error", "VALIDATION_ERROR", "`old_results` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`old_results` must be a non-empty string", old_results=old_results)
    if not isinstance(new_results, str) or not new_results.strip():
        _append_log("error", "VALIDATION_ERROR", "`new_results` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`new_results` must be a non-empty string", new_results=new_results)

    project, root_abs, resolved = _choose_project_for_paths(old_results, new_results)
    if project is None:
        _append_log(
            "error",
            "UNAUTHORIZED",
            "No active project workspace can serve this request (paths must resolve under an active project's mcp_root_path).",
            extra={"old_results": old_results, "new_results": new_results},
        )
        return _err(
            "UNAUTHORIZED",
            "No active project workspace can serve this request (paths must resolve under an active project's mcp_root_path).",
            old_results=old_results,
            new_results=new_results,
        )
    old_abs, new_abs = resolved[0], resolved[1]

    old_loaded = _load_results_payload(old_abs)
    if "error" in old_loaded:
        _append_log("error", old_loaded["error"]["error"]["code"], old_loaded["error"]["error"]["message"], project_id=project.get("id"), extra={"old_results": old_abs})
        return old_loaded["error"]
    new_loaded = _load_results_payload(new_abs)
    if "error" in new_loaded:
        _append_log("error", new_loaded["error"]["error"]["code"], new_loaded["error"]["error"]["message"], project_id=project.get("id"), extra={"new_results": new_abs})
        return new_loaded["error"]

    old_fps = old_loaded["fingerprints"]
    new_fps = new_loaded["fingerprints"]

    added = sorted(list(new_fps - old_fps))
    removed = sorted(list(old_fps - new_fps))
    unchanged = sorted(list(old_fps & new_fps))

    comparison_obj = {
        "old_results": old_abs,
        "new_results": new_abs,
        "old_source": old_loaded.get("source"),
        "new_source": new_loaded.get("source"),
        "counts": {
            "added": len(added),
            "removed": len(removed),
            "unchanged": len(unchanged),
            "old_total": len(old_fps),
            "new_total": len(new_fps),
        },
        "added_fingerprints": added,
        "removed_fingerprints": removed,
        "unchanged_fingerprints": unchanged,
    }

    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []
    art_id = _gen_id("semart")
    now = _now()
    art = {
        "id": art_id,
        "project_id": project.get("id"),
        "scan_id": None,
        "source_results_file_path": old_abs,  # per schema required; store old as "source"
        "type": "comparison",
        "output_file_path": None,
        "export_format": None,
        "filter_criteria": None,
        "analysis_summary": None,
        "comparison": comparison_obj,
        "status": "ready",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    artifacts.append(art)
    _save("artifacts.json", artifacts)

    _append_log("ok", project_id=project.get("id"), artifact_id=art_id)
    return {"artifact": art, "comparison": comparison_obj}

def list_projects(status=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_code, message=None, extra=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "timestamp": now,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "project_id": None,
            "artifact_id": None,
        }
        if message:
            row["message"] = message
        if isinstance(extra, dict):
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            _log("list_projects", "VALIDATION_ERROR", "status must be one of: active, archived")
            return _err("VALIDATION_ERROR", "status must be one of: active, archived")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        _log("list_projects", "CONFLICT", "projects store is corrupted")
        return _err("CONFLICT", "projects store is corrupted")

    rows = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if status is not None and p.get("status") != status:
            continue
        rows.append(p)

    # order by created_at desc (fallback to id)
    def _key(p):
        c = p.get("created_at")
        return (c if isinstance(c, str) else "", p.get("id") or "")
    rows.sort(key=_key, reverse=True)

    # No explicit credential/auth model in schema; ambient auth allows enumeration.
    _log("list_projects", "OK", extra={"count": len(rows), "filtered_by_status": status is not None})
    return {
        "projects": rows,
        "count": len(rows)
    }

def create_project(name, mcp_root_path, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_project"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(status, code=None, message=None, project_id=None, extra=None):
        logs = _ensure_logs()
        rid = f"req_{int(time.time()*1000)}_{hashlib.sha1((endpoint+str(time.time())).encode()).hexdigest()[:10]}"
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if project_id:
            row["project_id"] = project_id
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha1(str(time.time()).encode()).hexdigest()[:12]}"

    # Validate
    if not isinstance(name, str) or not name.strip():
        _append_log("error", "VALIDATION_ERROR", "`name` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`name` must be a non-empty string", name=name)
    if not isinstance(mcp_root_path, str) or not mcp_root_path.strip():
        _append_log("error", "VALIDATION_ERROR", "`mcp_root_path` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`mcp_root_path` must be a non-empty string", mcp_root_path=mcp_root_path)
    if not os.path.isabs(mcp_root_path):
        _append_log("error", "VALIDATION_ERROR", "Constraint violated: mcp_root_path must be absolute.", extra={"mcp_root_path": mcp_root_path})
        return _err("VALIDATION_ERROR", "Constraint violated: mcp_root_path must be absolute.", mcp_root_path=mcp_root_path)

    root_abs = os.path.realpath(os.path.abspath(mcp_root_path))
    if not os.path.isdir(root_abs):
        _append_log("error", "NOT_FOUND", "Root directory does not exist.", extra={"mcp_root_path": root_abs})
        return _err("NOT_FOUND", "Root directory does not exist.", mcp_root_path=root_abs)

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    # Enforce unique(name)
    for p in projects:
        if isinstance(p, dict) and p.get("name") == name:
            _append_log("error", "CONFLICT", "Constraint violated: project name must be unique.", project_id=p.get("id"))
            return _err("CONFLICT", "Constraint violated: project name must be unique.", name=name)

    now = _now()
    proj_id = _gen_id("semproj")
    proj = {
        "id": proj_id,
        "name": name,
        "mcp_root_path": root_abs,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }
    projects.append(proj)
    _save("projects.json", projects)

    _append_log("ok", project_id=proj_id)
    return {"project": proj}

def update_project(id, name=None, status=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, latency_ms, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if error:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = datetime.datetime.utcnow()

    if not isinstance(id, str) or not id.strip():
        latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
        err = _err("VALIDATION_ERROR", "Invalid 'id'; must be a non-empty string.")
        _log("update_project", "error", latency, error=err["error"])
        return err

    if name is not None and (not isinstance(name, str) or not name.strip()):
        latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
        err = _err("VALIDATION_ERROR", "Invalid 'name'; must be a non-empty string when provided.")
        _log("update_project", "error", latency, error=err["error"])
        return err

    if status is not None:
        if not isinstance(status, str):
            latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
            err = _err("VALIDATION_ERROR", "Invalid 'status'; must be a string.")
            _log("update_project", "error", latency, error=err["error"])
            return err
        if status not in ("active", "archived"):
            latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
            err = _err("VALIDATION_ERROR", "Invalid 'status' value.", allowed=["active", "archived"])
            _log("update_project", "error", latency, error=err["error"])
            return err

    if name is None and status is None:
        latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
        err = _err("VALIDATION_ERROR", "No mutable fields provided; supply 'name' and/or 'status'.")
        _log("update_project", "error", latency, error=err["error"])
        return err

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    idx = None
    for i, p in enumerate(projects):
        if isinstance(p, dict) and p.get("id") == id:
            idx = i
            break

    if idx is None:
        latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
        err = _err("NOT_FOUND", "Project not found.", id=id)
        _log("update_project", "error", latency, error=err["error"])
        return err

    proj = projects[idx]

    # unique(name)
    if name is not None and name != proj.get("name"):
        for p in projects:
            if isinstance(p, dict) and p.get("name") == name:
                latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
                err = _err("CONFLICT", "Project name already exists.", name=name)
                _log("update_project", "error", latency, error=err["error"])
                return err

    # lifecycle transitions
    if status is not None and status != proj.get("status"):
        cur = proj.get("status")
        allowed = {"active": ["archived"], "archived": []}
        if cur not in allowed or status not in allowed[cur]:
            latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
            err = _err("INVALID_TRANSITION", "Invalid project status transition.", from_status=cur, to_status=status)
            _log("update_project", "error", latency, error=err["error"])
            return err
        proj["status"] = status

    if name is not None:
        proj["name"] = name

    proj["updated_at"] = _now()
    projects[idx] = proj
    _save("projects.json", projects)

    latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
    _log("update_project", "ok", latency)
    return {"project": proj}

def list_scans(project_id, status=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, latency_ms, error=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if error:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = datetime.datetime.utcnow()

    if not isinstance(project_id, str) or not project_id.strip():
        latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
        err = _err("VALIDATION_ERROR", "Invalid 'project_id'; must be a non-empty string.")
        _log("list_scans", "error", latency, error=err["error"])
        return err

    if status is not None:
        if not isinstance(status, str):
            latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
            err = _err("VALIDATION_ERROR", "Invalid 'status'; must be a string.")
            _log("list_scans", "error", latency, error=err["error"])
            return err
        allowed = ("queued", "running", "succeeded", "failed", "cancelled")
        if status not in allowed:
            latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
            err = _err("VALIDATION_ERROR", "Invalid 'status' value.", allowed=list(allowed))
            _log("list_scans", "error", latency, error=err["error"])
            return err

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int):
        latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
        err = _err("VALIDATION_ERROR", "Invalid 'page_size'; must be an integer.")
        _log("list_scans", "error", latency, error=err["error"])
        return err
    if page_size < 1 or page_size > 200:
        latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
        err = _err("VALIDATION_ERROR", "'page_size' out of range; must be between 1 and 200.")
        _log("list_scans", "error", latency, error=err["error"])
        return err

    offset = 0
    if page_token is not None:
        if not isinstance(page_token, str):
            latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
            err = _err("VALIDATION_ERROR", "Invalid 'page_token'; must be a string.")
            _log("list_scans", "error", latency, error=err["error"])
            return err
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8")).decode("utf-8")
            payload = json.loads(raw)
            if not isinstance(payload, dict) or payload.get("project_id") != project_id:
                raise ValueError("bad token")
            off = payload.get("offset")
            if not isinstance(off, int) or off < 0:
                raise ValueError("bad offset")
            offset = off
        except Exception:
            latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
            err = _err("VALIDATION_ERROR", "Invalid 'page_token'.")
            _log("list_scans", "error", latency, error=err["error"])
            return err

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    if not any(isinstance(p, dict) and p.get("id") == project_id for p in projects):
        latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
        err = _err("NOT_FOUND", "Project not found.", project_id=project_id)
        _log("list_scans", "error", latency, error=err["error"])
        return err

    scans = _load("scans.json")
    if not isinstance(scans, list):
        scans = []

    rows = [s for s in scans if isinstance(s, dict) and s.get("project_id") == project_id]
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]

    # Order by created_at desc (fallback updated_at, then id)
    def _k(s):
        return (s.get("created_at") or "", s.get("updated_at") or "", s.get("id") or "")

    rows.sort(key=_k, reverse=True)

    total = len(rows)
    page = rows[offset: offset + page_size]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_token = None
    if has_more:
        payload = {"project_id": project_id, "offset": next_offset}
        next_token = base64.urlsafe_b64encode(json.dumps(payload).encode("utf-8")).decode("utf-8")

    latency = (datetime.datetime.utcnow() - t0).total_seconds() * 1000
    _log("list_scans", "ok", latency)
    return {
        "scans": page,
        "page": {
            "total": total,
            "page_size": page_size,
            "offset": offset,
            "has_more": has_more,
            "next_page_token": next_token,
        },
    }

def get_artifact(id, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0027000" if __import__("os").path.isdir("./environment_mix/0027000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_artifact"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(status, code=None, message=None, artifact_id=None, extra=None):
        logs = _ensure_logs()
        rid = f"req_{int(time.time()*1000)}_{hashlib.sha1((endpoint+str(time.time())).encode()).hexdigest()[:10]}"
        row = {
            "id": rid,
            "endpoint": endpoint,
            "status": status,
            "error_code": code,
            "error_message": message,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if artifact_id:
            row["artifact_id"] = artifact_id
        if isinstance(extra, dict) and extra:
            row["extra"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(id, str) or not id.strip():
        _append_log("error", "VALIDATION_ERROR", "`id` must be a non-empty string")
        return _err("VALIDATION_ERROR", "`id` must be a non-empty string", id=id)

    artifacts = _load("artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    art = None
    for a in artifacts:
        if isinstance(a, dict) and a.get("id") == id:
            art = a
            break

    if art is None:
        # If the caller passed a non-artifact id, still return NOT_FOUND (but helpfully indicate it)
        _append_log("error", "NOT_FOUND", "Artifact not found.", artifact_id=id)
        return _err("NOT_FOUND", "Artifact not found.", id=id)

    _append_log("ok", artifact_id=id)
    return {"artifact": art}
